import { Controller, Get, Post, Body, Param, Query, Module, Injectable, ParseIntPipe, DefaultValuePipe, BadRequestException, NotFoundException, HttpCode, Header, Redirect } from "@nestjs/common";
import { NestFactory } from "@nestjs/core";

@Controller()
class LessonController {

@Post("books") create(@Body() body: { title?: unknown }) { if (typeof body?.title !== "string") throw new BadRequestException("Title needed"); return { title: body.title }; }
}
@Module({ controllers: [LessonController], providers: [] })
class AppModule {}
async function main() { const app = await NestFactory.create(AppModule); await app.listen(3000, "127.0.0.1"); }
void main();
